-- Уточнение системы сигналов по прямой правке пользователя, на реальном
-- примере: 1) сигнал был назначен на table-ячейку БЕЗ options ("try", одна
-- форма без альтернативы) — там ошибка физически невозможна, сигнал был
-- бессмысленным; 2) текст сигнала начинался с "А здесь..." — предполагает,
-- что до него уже показывался другой сигнал, а сигнал может сработать
-- ПЕРВЫМ; 3) для слота "to" оказалось, что нужное объяснение УЖЕ есть в
-- уроке (обычная финальная ветка table_wrong) — вместо новой ноды-спутника
-- просто указали на неё через signals[].ref.
--
-- Одно из трёх старых правил (сама механика signals) не трогаем — только
-- обновляем текст правила про размещение (добавляем исключение для
-- переиспользованных нод) и добавляем два новых правила + правило про
-- переиспользование.
--
-- Проверено на конфликт: rule_text уникальны, не пересекаются с существующими.
update public.lesson_rules
set rule_text = 'Система размещения нод-сигналов (companion, на которую ссылается signals[].ref): НЕ ставь её в общий ряд сценария и не допускай, чтобы она легла поверх другой ноды. Сигнальные ноды, СПЕЦИАЛЬНО построенные под конкретный слот (нет другой роли в графе), идут в своём отдельном ряду НИЖЕ родителя (той, что содержит signals) — тот же вертикальный шаг, что у обычных побочных веток, выровнены по x номером слота: слот 0 — тот же x, что у родителя; слот 1 — на один обычный шаг правее; слот 2 — ещё на шаг и т.д. Если сигнал ссылается на уже СУЩЕСТВУЮЩУЮ ноду основного потока (см. отдельный принцип про переиспользование) — эта нода остаётся на своём обычном месте в сценарии, никуда её переносить не нужно, дашед-связь сигнала просто дотянется до неё через холст. Сигнальные ноды подчиняются ОБЩЕМУ правилу коллизий позиций наравне со всеми остальными (dx<350 И dy<200 одновременно — коллизия) — прогоняй аудит по ВСЕМ нодам без исключения, включая сигнальные, их легко забыть, раз они не часть основной цепочки. В проверке достижимости графа (BFS от n1 по triggers.then) сигнальная нода не имеет своего места в основном потоке — считай её достижимой отдельно, если на неё ссылается ЛЮБОЙ signals[].ref где-либо в уроке.'
where rule_text like 'Система размещения нод-сигналов%'
  and rule_text not like '%СПЕЦИАЛЬНО построенные%';

insert into public.lesson_rules (rule_text, sort_order, category)
select
  'Текст сигнальной подсказки должен читаться САМОДОСТАТОЧНО, без привязки к порядку вызова: сигнал срабатывает на ПЕРВОМ неверном слоте слева направо, и это может быть любой слот из назначенных — никакой гарантии, что до него уже показывался другой сигнал. НЕ начинай текст сигнала со слов, предполагающих продолжение чего-то предыдущего («А здесь...», «Тут ещё и...», «Также...») — если этот сигнал окажется первым, что видит ученик, такое начало прозвучит бессвязно. Пиши каждый сигнал так, будто это первая и единственная подсказка в уроке. Плохо: «А здесь — форма глагола, приглядись» (предполагает, что до этого уже что-то показали). Хорошо: «to — мостик между двумя глаголами, try и speak» (самостоятельная мысль).',
  178,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'Текст сигнальной подсказки должен читаться САМОДОСТАТОЧНО%'
);

insert into public.lesson_rules (rule_text, sort_order, category)
select
  'НЕ ставь сигнал на слот, где ошибка физически НЕВОЗМОЖНА. У table-ячейки без поля options есть только ОДНО значение — тапнуть иначе просто нечем, значит подсказка вида «проверь форму» для такой ячейки бессмысленна: перепутать там нечего. Сигнал имеет смысл только там, где у слота есть РЕАЛЬНАЯ альтернатива — table-ячейка С options (несколько вариантов на выбор) или слово вне таблицы (extra), которое можно перепутать местом/дистрактором. Перед тем как назначить сигнал на слот, спроси: «а что именно ученик мог перепутать, чтобы здесь оказалось неверное значение?» — если ответа нет, сигнал этому слоту не нужен.',
  179,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'НЕ ставь сигнал на слот, где ошибка физически НЕВОЗМОЖНА%'
);

insert into public.lesson_rules (rule_text, sort_order, category)
select
  'Прежде чем писать НОВУЮ ноду-сигнал — проверь, нет ли в уроке уже готовой ноды с подходящим объяснением (например, финальная ветка после трёх попыток той же самой ошибки, table_wrong/phrase_wrong/word_wrong). signals[].ref может ссылаться на ЛЮБУЮ ноду урока, в том числе уже стоящую в основном потоке графа — не обязательно строить отдельного «спутника» под каждый слот. Так подсказка не тратится впустую на дубль уже написанного текста, а ученик может увидеть то же объяснение раньше, бесплатно, при первой же ошибке, а не только выработав все три попытки. Компромисс: если ученик всё же дойдёт до этой ноды и обычным путём (все три попытки потрачены на ДРУГИХ слотах) — та же самая нода-объяснение может показаться в чате второй раз, это нормально, не баг.',
  180,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'Прежде чем писать НОВУЮ ноду-сигнал%'
);
